</head><body>
<header class="studio-header"><a class="brand" href="<?= site_url('dashboard') ?>"><img src="<?= base_url('assets/img/printrivo_dark_logo.png') ?>" alt="Printrivo" width="110" height="60"><span class="studio-brand-title">Image Studio</span></a><div class="header-actions"><a class="studio-button" href="<?= site_url('dashboard') ?>">Dashboard</a><?= view('partials/report_bug_button') ?><button id="open">Open image</button><button id="export" class="primary" disabled>Export PNG</button><button id="send-print" disabled title="Send one copy of this artwork to CSW using your account details">Send to printer</button></div></header>
<input id="file" type="file" accept="image/png,image/jpeg,image/webp" hidden>
<div class="document-bar"><span id="filename">Untitled artwork</span><div><button id="undo" disabled>Undo</button><button id="redo" disabled>Redo</button><button id="reset" disabled>Reset image</button><button id="clear-image" disabled>Clear image</button></div></div>
<main class="studio-layout">
<aside class="tools panel" aria-label="Image editing tools">
<h1 class="eyebrow">PREPARE YOUR ARTWORK</h1>
<fieldset id="image-tools" disabled>
<details id="background-panel"><summary>Background &amp; trim</summary><details id="background-removal"><summary>Remove background</summary><p class="hint">Keep your background, or remove an edge-connected solid color. Best for artwork on plain backgrounds.</p><label>Background tolerance <input id="tolerance" type="range" min="0" max="120" value="20"></label><label>Background color<select id="bg-source"><option value="auto">Auto (image corners)</option><option value="custom">Choose color</option></select></label><label>Color to remove<input id="bg-color" type="color" value="#ffffff"></label><label>Removal area<select id="bg-area"><option value="edges">Connected to edges</option><option value="all">All matching areas (including holes)</option></select></label><label>Edge softness<input id="bg-feather" type="range" min="0" max="40" value="10"></label><p class="hint">All matching areas can also remove that color inside your artwork. For complex photo backgrounds, this color-based tool is not subject-aware.</p><button id="remove-bg">Apply background removal</button></details><label>Trim padding (px)<input id="trim-padding" type="number" value="2" min="0" max="30000" step="1"></label><button id="trim">Trim to Artwork</button>
<details id="pixel-crop"><summary>Exact pixel crop</summary><div class="grid"><label>Crop X (px)<input id="crop-x" type="number" min="0" value="0"></label><label>Crop Y (px)<input id="crop-y" type="number" min="0" value="0"></label><label>Width (px)<input id="crop-w" type="number" min="1" value="1"></label><label>Height (px)<input id="crop-h" type="number" min="1" value="1"></label></div><button id="crop">Apply crop</button></details><button id="center-artwork">Center Artwork</button><div id="background-tools"></div></details>
<details id="resize-panel"><summary>Resize image &amp; print</summary><div class="grid"><label>Print width (in)<input id="print-width" type="number" min="0.01" step="0.01" value="1"></label><label>Print height (in)<input id="print-height" type="number" min="0.01" step="0.01" value="1"></label></div><label class="checkbox"><input id="lock-ratio" type="checkbox" checked> Keep proportions</label><label>Export DPI<select id="dpi"><option>150</option><option selected>300</option><option>600</option></select></label><button id="resize">Apply resize</button><div class="grid"><button id="upscale2">Upscale 2×</button><button id="upscale4">Upscale 4×</button></div><p class="hint">Enter inches and DPI, then apply resize. Unlock proportions to set width and height independently (stretches artwork and flattens text). Smooth upscaling cannot recover missing detail. Maximum 256 megapixels and 30,000 pixels per side. Large edits need more device memory.</p><button id="upscale-print">Upscale for 300 DPI</button><p id="print-recommendations" class="hint"></p><p id="resize-info" class="hint" aria-live="polite"></p><div class="grid"><button id="rotate">Rotate 90°</button><button id="flip">Flip horizontal</button></div><p class="hint">Rotate and flip flatten text into the image. Undo restores editable layers.</p></details>
<details id="clean-panel"><summary>Clean artwork</summary><div id="clean-tools"></div></details>
<details id="colors-panel"><summary>Colors</summary><details id="color-adjustments"><summary>Color adjustments</summary><label>Brightness<input id="brightness" type="range" min="-100" max="100" value="0"></label><label>Contrast<input id="contrast" type="range" min="-100" max="100" value="0"></label><label>Saturation<input id="saturation" type="range" min="0" max="200" value="100"></label><button id="colors">Apply adjustments</button><div class="grid"><label>Replace color<input id="from-color" type="color" value="#ffffff"></label><label>With color<input id="to-color" type="color" value="#000000"></label></div><label>Color tolerance<input id="color-tolerance" type="range" min="0" max="100" value="15"></label><button id="replace-color">Replace matching color</button><p class="hint">Color adjustments affect the image. Text colors remain independently editable.</p></details>
<div id="color-tools"></div></details>
<details id="halftone-panel"><summary>Halftone creator</summary>
<label>Preset<select id="ht-preset"><option value="standard">Standard</option><option value="custom">Custom</option><option value="fine">Fine</option><option value="bold">Bold</option><option value="vintage">Vintage</option><option value="high-contrast">High Contrast</option></select></label>
<h3>Dots</h3>
<label>Dot shape<select id="ht-shape"><option value="circle">Circle</option><option value="ellipse">Ellipse</option><option value="square">Square</option><option value="diamond">Diamond</option><option value="line">Line</option></select></label>
<label>Spacing unit<select id="ht-unit"><option value="pixels">Pixels</option><option value="inches">Inches</option></select></label>
<div class="ht-control"><label for="ht-spacing">Dot spacing <span class="ht-help" tabindex="0" title="Distance between dot centers. Inches use the selected document export DPI." aria-label="Distance between dot centers. Inches use the selected document export DPI.">?</span></label><div class="ht-pair"><input type="range" id="ht-spacing-range" min="3" max="100" step="1" value="12" aria-label="Dot spacing"><input type="number" id="ht-spacing" min="3" max="100" step="1" value="12" aria-label="Dot spacing value"></div></div>
<div class="ht-control"><label for="ht-maxSize">Max dot size (%)</label><div class="ht-pair"><input type="range" id="ht-maxSize-range" min="10" max="150" step="1" value="100" aria-label="Max dot size (%)"><input type="number" id="ht-maxSize" min="10" max="150" step="1" value="100" aria-label="Max dot size (%) value"></div></div>
<div class="ht-control"><label for="ht-minSize">Min dot size (%)</label><div class="ht-pair"><input type="range" id="ht-minSize-range" min="0" max="100" step="1" value="0" aria-label="Min dot size (%)"><input type="number" id="ht-minSize" min="0" max="100" step="1" value="0" aria-label="Min dot size (%) value"></div></div>
<div class="ht-control"><label for="ht-angle">Angle (°) <span class="ht-help" tabindex="0" title="Rotates the screen grid and dot shapes together." aria-label="Rotates the screen grid and dot shapes together.">?</span></label><div class="ht-pair"><input type="range" id="ht-angle-range" min="0" max="180" step="1" value="45" aria-label="Angle (°)"><input type="number" id="ht-angle" min="0" max="180" step="1" value="45" aria-label="Angle (°) value"></div></div>
<button id="ht-reset-dots" type="button">Reset dot settings</button><h3>Tones</h3>
<label>Tone mode<select id="ht-mode"><option value="dark">Dark artwork</option><option value="light">Light artwork</option><option value="invert">Invert (reverse dark tones)</option></select></label>
<div class="ht-control"><label for="ht-brightness">Brightness</label><div class="ht-pair"><input type="range" id="ht-brightness-range" min="-100" max="100" step="1" value="0" aria-label="Brightness"><input type="number" id="ht-brightness" min="-100" max="100" step="1" value="0" aria-label="Brightness value"></div></div>
<div class="ht-control"><label for="ht-contrast">Contrast</label><div class="ht-pair"><input type="range" id="ht-contrast-range" min="-100" max="100" step="1" value="0" aria-label="Contrast"><input type="number" id="ht-contrast" min="-100" max="100" step="1" value="0" aria-label="Contrast value"></div></div>
<div class="ht-control"><label for="ht-gamma">Gamma <span class="ht-help" tabindex="0" title="Adjusts midtone ink coverage without changing the black and white endpoints." aria-label="Adjusts midtone ink coverage without changing the black and white endpoints.">?</span></label><div class="ht-pair"><input type="range" id="ht-gamma-range" min="0.1" max="3" step="0.1" value="1" aria-label="Gamma"><input type="number" id="ht-gamma" min="0.1" max="3" step="0.1" value="1" aria-label="Gamma value"></div></div>
<label class="checkbox"><input id="ht-thresholdEnabled" type="checkbox" >Enable threshold</label>
<div class="ht-control"><label for="ht-threshold">Threshold</label><div class="ht-pair"><input type="range" id="ht-threshold-range" min="0" max="255" step="1" value="128" aria-label="Threshold"><input type="number" id="ht-threshold" min="0" max="255" step="1" value="128" aria-label="Threshold value"></div></div>
<label>Ink color<input id="ht-ink" type="color" value="#000000"></label>
<label>Background<select id="ht-background"><option value="transparent">Transparent</option><option value="white">White</option><option value="custom">Custom color</option></select></label>
<label id="ht-background-label" hidden>Background color<input id="ht-backgroundColor" type="color" value="#ffffff"></label><details class="ht-advanced"><summary>Advanced</summary>
<label>Sampling quality<select id="ht-quality"><option value="balanced">Balanced</option><option value="fast">Fast</option><option value="high">High</option></select></label>
<div class="ht-control"><label for="ht-softness">Edge softness</label><div class="ht-pair"><input type="range" id="ht-softness-range" min="0" max="100" step="1" value="0" aria-label="Edge softness"><input type="number" id="ht-softness" min="0" max="100" step="1" value="0" aria-label="Edge softness value"></div></div>
<div class="ht-control"><label for="ht-gain">Dot gain (%) <span class="ht-help" tabindex="0" title="Adds or removes ink coverage to compensate for print gain." aria-label="Adds or removes ink coverage to compensate for print gain.">?</span></label><div class="ht-pair"><input type="range" id="ht-gain-range" min="-50" max="50" step="1" value="0" aria-label="Dot gain (%)"><input type="number" id="ht-gain" min="-50" max="50" step="1" value="0" aria-label="Dot gain (%) value"></div></div>
<label class="checkbox"><input id="ht-preserve" type="checkbox" checked>Preserve source transparency</label>
<label class="checkbox"><input id="ht-clip" type="checkbox" checked>Clip dots to source alpha</label>
<label class="checkbox"><input id="ht-removeTiny" type="checkbox" checked>Remove tiny dots</label>
<div class="ht-control"><label for="ht-minPrintable">Minimum printable dot (px) <span class="ht-help" tabindex="0" title="Dots smaller than this document-pixel size are omitted. Confirm the minimum with your printer." aria-label="Dots smaller than this document-pixel size are omitted. Confirm the minimum with your printer.">?</span></label><div class="ht-pair"><input type="range" id="ht-minPrintable-range" min="0" max="100" step="0.1" value="1" aria-label="Minimum printable dot (px)"><input type="number" id="ht-minPrintable" min="0" max="100" step="0.1" value="1" aria-label="Minimum printable dot (px) value"></div></div>
<div class="ht-control"><label for="ht-offsetX">Grid offset X (px)</label><div class="ht-pair"><input type="range" id="ht-offsetX-range" min="-100" max="100" step="1" value="0" aria-label="Grid offset X (px)"><input type="number" id="ht-offsetX" min="-100" max="100" step="1" value="0" aria-label="Grid offset X (px) value"></div></div>
<div class="ht-control"><label for="ht-offsetY">Grid offset Y (px)</label><div class="ht-pair"><input type="range" id="ht-offsetY-range" min="-100" max="100" step="1" value="0" aria-label="Grid offset Y (px)"><input type="number" id="ht-offsetY" min="-100" max="100" step="1" value="0" aria-label="Grid offset Y (px) value"></div></div>
</details><h3>Print information</h3><p id="ht-print" class="hint">Open an image to see print dimensions.</p>
<label>Preview<select id="ht-preview"><option value="halftone">Halftone</option><option value="original">Original</option></select></label>
<p id="ht-status" class="hint" role="status" aria-live="polite"></p><div class="grid"><button id="ht-reset" type="button">Reset</button><button id="ht-cancel" type="button">Cancel Preview</button></div><button id="halftone" type="button">Apply Halftone</button><p class="hint">Preview only changes the image layer. Apply before exporting; text stays editable.</p></details>
<details id="effects-panel"><summary>Effects</summary><div id="effect-tools"></div></details>
</fieldset></aside>
<section class="workspace" aria-label="Artwork canvas"><div class="canvas-toolbar"><span id="dimensions">Open an image to begin</span><button id="measure" disabled aria-pressed="false">Measure</button><label class="checkbox"><input id="mirror-preview" type="checkbox"> Mirror for transfer</label><label>Zoom <select id="zoom"><option value="fit">Fit</option><option value=".25">25%</option><option value=".5">50%</option><option value="1">100%</option><option value="2">200%</option></select></label><label>Preview <select id="backdrop"><option value="checker">Transparency</option><option value="white">White</option><option value="dark">Dark</option></select></label></div><div id="stage" class="stage"><div id="empty"><strong>Your artwork, ready for its next step.</strong><p>Drop one PNG, JPG, or WebP here.</p><button id="open-empty" class="primary">Open image</button><small>Edits stay in your browser. Your original file is untouched.</small></div><canvas id="canvas" hidden aria-label="Image preview. Use text position inputs for precise placement."></canvas></div><p id="measurement" class="hint" hidden></p><p id="mirror-notice" class="hint" hidden>⚠ MIRROR ENABLED — exported artwork will be horizontally mirrored. Document pixels are unchanged.</p><p id="status" role="status" aria-live="polite">Open a single image. Nothing is removed or changed automatically.</p></section>
<aside class="inspector panel" aria-label="Print check and text layers">
<section class="print-check"><h2>PRINT CHECK</h2><p id="print-info" class="hint">Image dimensions, transparency, and output size appear here.</p><div id="preflight-checks"></div><p id="preflight-summary" role="status">Open an image to check whether your artwork is ready for print.</p><section id="quick-fixes-section" hidden><h3>QUICK FIXES</h3><div id="quick-fixes"></div></section><h3>STATUS</h3><p id="preflight-status" role="status">NO IMAGE</p></section>
<details id="text-panel"><summary>Text &amp; layers</summary><fieldset id="text-tools" disabled><button id="add-text">+ Add text layer</button><p class="hint">Fonts use those available on your device. Load your own font for more choices.</p><label>Load font (.ttf, .otf, .woff, .woff2)<input id="font-file" type="file" accept=".ttf,.otf,.woff,.woff2"></label><label>Selected layer<select id="layers"><option value="">Image only</option></select></label><div id="text-properties" hidden><label>Text<textarea id="text" rows="3" maxlength="1000">Your text</textarea></label><div class="grid"><label>Font<select id="font"><option value="Arial">Arial</option><option value="Georgia">Georgia</option><option value="Verdana">Verdana</option><option value="Impact">Impact</option><option value="monospace">Monospace</option><option value="Trebuchet MS">Trebuchet MS</option><option value="Times New Roman">Times New Roman</option><option value="Courier New">Courier New</option><option value="Tahoma">Tahoma</option></select></label><label>Size (px)<input id="font-size" type="number" min="6" max="2000" value="72"></label><label>Color<input id="text-color" type="color" value="#000000"></label><label>Weight<select id="weight"><option value="400">Regular</option><option value="700">Bold</option></select></label><label>X (px)<input id="text-x" type="number" step="1" value="0"></label><label>Y (px)<input id="text-y" type="number" step="1" value="0"></label></div><button id="delete-text">Delete text layer</button><p class="hint">Drag text on the canvas or enter its position. New layers appear above earlier layers.</p></div></fieldset></details></aside>
</main>
<dialog id="export-dialog" aria-labelledby="export-title"><h2 id="export-title">READY TO EXPORT</h2><p id="export-summary"></p><div id="export-issues"></div><h3>OPTIONS</h3><label class="checkbox"><input id="export-mirror" type="checkbox"> Mirror for transfer</label><label class="checkbox"><input id="export-trim" type="checkbox"> Trim transparent pixels</label><label class="checkbox"><input id="export-padding" type="checkbox"> Add transparent padding</label><label>Padding (px)<input id="export-pad" type="number" min="0" max="30000" step="1" value="50"></label><p id="export-error" role="alert"></p><div class="export-actions"><button id="export-cancel">Cancel</button><button id="export-fix">Go Back &amp; Fix</button><button id="export-confirm" class="primary">Export PNG</button></div></dialog>
